window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ae999b1b55c74dc"]={"versions": [{"id": "FIG-2ae999b1b55c74dc", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Architektur-Abhängigkeitsdiagramm (Component & Interface Dependency Diagram) gemäß AUTOSAR-Metamodell für die Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der durch den Functional Cluster (FC) <code>Log and Trace</code> bereitgestellten nativen Programmierschnittstelle (<code>Logger</code>) und deren querschnittlicher Abhängigkeiten (<code>«use»</code>) zu allen übrigen Standard-Functional-Clustern der AUTOSAR Adaptive Platform (Release R23-11, Kapitel 5.1).</li>\n<li><strong>Systemeinordnung:</strong> <code>Log and Trace</code> stellt das fundamentale Diagnose-, Tracing- und Protokollierungs-Rückgrat (<code>ara::log</code>) für Plattform-Daemons und Bibliotheken bereit, typischerweise mit Anbindung an das DLT-Protokoll (Diagnostic Log and Trace).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Bereitgestellte Schnittstelle:</strong></li>\n<li><code>«aapAPI, aapNativeInterface» Logger</code>: Zentrale C++ Abstraktion (<code>ara::log::Logger</code>) zur strukturierten und unstrukturierten Protokollierung.</li>\n<li><code>+ IsEnabled()</code>: Abfrage des aktiven Log-Zustands zur Vermeidung unnötiger Formatierungs-Overheads.</li>\n<li><code>+ Log(MsgId, Params)</code>: Direktes, ID-basiertes Logging für formatfreie oder vorkompilierte DLT-Nachrichten.</li>\n<li><code>+ LogDebug(): LogStream</code>, <code>+ LogError(): LogStream</code>, <code>+ LogFatal(): LogStream</code>, <code>+ LogInfo(): LogStream</code>, <code>+ LogVerbose(): LogStream</code>, <code>+ LogWarn(): LogStream</code>: Severity-spezifische Factory-Methoden zur Erzeugung typsicherer Streaming-Objekte (<code>ara::log::LogStream</code>).</li>\n<li><code>+ WithLevel(): LogStream</code>: Dynamische Festlegung des Log-Levels zur Laufzeit.</li>\n<li><strong>Realisierende Komponente:</strong></li>\n<li><code>«aapFunctionalCluster» Log and Trace</code>: Implementiert das <code>Logger</code>-Interface (Realization-Pfeil mit geschlossener, nicht ausgefüllter Spitze).</li>\n<li><strong>Konsumierende Functional Clusters (<code>«use»</code>-Beziehung):</strong></li>\n<li><strong>Daemon-basierte Cluster (<code>daemon-based</code>):</strong></li>\n<li><code>Execution Management</code> (Prozesslebenszyklus, POSIX-Initialisierung)</li>\n<li><code>State Management</code> (Systemzustandssteuerung)</li>\n<li><code>Diagnostic Management</code> (UDS/DoIP-Stack)</li>\n<li><code>Platform Health Management</code> (Watchdog, Alive-/Deadline-Supervision)</li>\n<li><code>Time Synchronization</code> (gPTP / IEEE 802.1AS)</li>\n<li><code>Intrusion Detection System Manager</code> (Security Event Logging)</li>\n<li><code>Communication Management</code> (Service-Oriented Communication via SOME/IP, IPC)</li>\n<li><code>Vehicle Update and Configuration Management</code> (Fahrzeugweite Update-Orchestrierung)</li>\n<li><code>Update and Configuration Management</code> (Lokales Software-Package-Handling)</li>\n<li><strong>Bibliotheks-/Nicht-Daemon-basierte Cluster:</strong></li>\n<li><code>Network Management</code> (Partielle Netzwerke, State Handling)</li>\n<li><code>Persistency</code> (Flash/EEPROM File & Key-Value Storage)</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchroner Aufrufkontext:</strong> Der aufrufende Functional Cluster instanziiert oder referenziert thread-lokal ein <code>Logger</code>-Objekt (gebunden an Application-ID/Context-ID).</li>\n<li><strong>Filterung & Stream-Generierung:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Interner oder expliziter Check via <code>IsEnabled()</code> gegen den aktuell konfigurierten Log-Level.</li>\n<li>Bei Freigabe Erzeugung des temporären <code>LogStream</code>-Objekts (Stack-basiert).</li>\n<li>Formatierung/Serialisierung der Parameter über den überladenen Shift-Operator <code>operator&lt;&lt;</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Asynchroner Flush & IPC:</strong></li>\n<li>Mit Zerstörung des temporären <code>LogStream</code>-Objekts am Ende des Full-Expressions (RAII) erfolgt die Commit-Operation.</li>\n<li>Übergabe der Nachricht an den lokalen Puffer bzw. Shared-Memory-Ringpuffer.</li>\n<li>Der <code>Log and Trace</code>-Hintergrund-Daemon holt die Daten asynchron ab und routet sie über Netzwerk (DLT over IP) oder UART, ohne den Aufrufer-Thread zu blockieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht-blockierendes Verhalten (Real-Time Safety):</strong> Da echtzeitkritische Cluster wie <code>Platform Health Management</code> und <code>Time Synchronization</code> denselben Logger nutzen, darf das Logging unter keinen Umständen blockieren (Zero-Allocation-Policy im Hot-Path, strikte Trennung von Erfassung und serialisiertem I/O-Transport).</li>\n<li><strong>Bootstrap-Dilemma & Early Logging:</strong></li>\n<li><code>Execution Management</code> startet als erster Plattform-Daemon und muss bereits loggen können, bevor der <code>Log and Trace</code>-Daemon betriebsbereit ist.</li>\n<li>Treiber- und Stack-Entwickler müssen einen Ringpuffer-Fallback (Local Buffer) für Plattform-Starts vorsehen, der nach Initialisierung von <code>Log and Trace</code> geleert wird.</li>\n<li><strong>Reentrancy & Thread-Safety:</strong> Alle Methoden der <code>Logger</code>-Schnittstelle müssen reentrant und threadsicher implementiert sein, da Cluster wie <code>Communication Management</code> massiv nebenläufig agieren.</li>\n<li><strong>Traceability & ASIL-Einstufung:</strong> Wenn Security- (IDSM) oder Safety-relevante (PHM) Cluster über <code>Logger</code> auditieren, müssen Datenverluste bei Pufferüberläufen (Buffer Overflow / Message Drop Counters) normativ erfasst und meldbar sein.</li>\n</ul>"}, {"id": "FIG-d7bf0075ebd9cd51", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Architektur-Abhängigkeitsdiagramm (Component & Interface Dependency Diagram) gemäß AUTOSAR-Metamodell für die Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der durch den Functional Cluster (FC) <code>Log and Trace</code> bereitgestellten nativen Programmierschnittstelle (<code>Logger</code>) und deren querschnittlicher Abhängigkeiten (<code>«use»</code>) zu allen übrigen Standard-Functional-Clustern der AUTOSAR Adaptive Platform (Release R23-11, Kapitel 5.1).</li>\n<li><strong>Systemeinordnung:</strong> <code>Log and Trace</code> stellt das fundamentale Diagnose-, Tracing- und Protokollierungs-Rückgrat (<code>ara::log</code>) für Plattform-Daemons und Bibliotheken bereit, typischerweise mit Anbindung an das DLT-Protokoll (Diagnostic Log and Trace).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Bereitgestellte Schnittstelle:</strong></li>\n<li><code>«aapAPI, aapNativeInterface» Logger</code>: Zentrale C++ Abstraktion (<code>ara::log::Logger</code>) zur strukturierten und unstrukturierten Protokollierung.</li>\n<li><code>+ IsEnabled()</code>: Abfrage des aktiven Log-Zustands zur Vermeidung unnötiger Formatierungs-Overheads.</li>\n<li><code>+ Log(MsgId, Params)</code>: Direktes, ID-basiertes Logging für formatfreie oder vorkompilierte DLT-Nachrichten.</li>\n<li><code>+ LogDebug(): LogStream</code>, <code>+ LogError(): LogStream</code>, <code>+ LogFatal(): LogStream</code>, <code>+ LogInfo(): LogStream</code>, <code>+ LogVerbose(): LogStream</code>, <code>+ LogWarn(): LogStream</code>: Severity-spezifische Factory-Methoden zur Erzeugung typsicherer Streaming-Objekte (<code>ara::log::LogStream</code>).</li>\n<li><code>+ WithLevel(): LogStream</code>: Dynamische Festlegung des Log-Levels zur Laufzeit.</li>\n<li><strong>Realisierende Komponente:</strong></li>\n<li><code>«aapFunctionalCluster» Log and Trace</code>: Implementiert das <code>Logger</code>-Interface (Realization-Pfeil mit geschlossener, nicht ausgefüllter Spitze).</li>\n<li><strong>Konsumierende Functional Clusters (<code>«use»</code>-Beziehung):</strong></li>\n<li><strong>Daemon-basierte Cluster (<code>daemon-based</code>):</strong></li>\n<li><code>Execution Management</code> (Prozesslebenszyklus, POSIX-Initialisierung)</li>\n<li><code>State Management</code> (Systemzustandssteuerung)</li>\n<li><code>Diagnostic Management</code> (UDS/DoIP-Stack)</li>\n<li><code>Platform Health Management</code> (Watchdog, Alive-/Deadline-Supervision)</li>\n<li><code>Time Synchronization</code> (gPTP / IEEE 802.1AS)</li>\n<li><code>Intrusion Detection System Manager</code> (Security Event Logging)</li>\n<li><code>Communication Management</code> (Service-Oriented Communication via SOME/IP, IPC)</li>\n<li><code>Vehicle Update and Configuration Management</code> (Fahrzeugweite Update-Orchestrierung)</li>\n<li><code>Update and Configuration Management</code> (Lokales Software-Package-Handling)</li>\n<li><strong>Bibliotheks-/Nicht-Daemon-basierte Cluster:</strong></li>\n<li><code>Network Management</code> (Partielle Netzwerke, State Handling)</li>\n<li><code>Persistency</code> (Flash/EEPROM File & Key-Value Storage)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchroner Aufrufkontext:</strong> Der aufrufende Functional Cluster instanziiert oder referenziert thread-lokal ein <code>Logger</code>-Objekt (gebunden an Application-ID/Context-ID).</li>\n<li><strong>Filterung & Stream-Generierung:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Interner oder expliziter Check via <code>IsEnabled()</code> gegen den aktuell konfigurierten Log-Level.</li>\n<li>Bei Freigabe Erzeugung des temporären <code>LogStream</code>-Objekts (Stack-basiert).</li>\n<li>Formatierung/Serialisierung der Parameter über den überladenen Shift-Operator <code>operator&lt;&lt;</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Asynchroner Flush & IPC:</strong></li>\n<li>Mit Zerstörung des temporären <code>LogStream</code>-Objekts am Ende des Full-Expressions (RAII) erfolgt die Commit-Operation.</li>\n<li>Übergabe der Nachricht an den lokalen Puffer bzw. Shared-Memory-Ringpuffer.</li>\n<li>Der <code>Log and Trace</code>-Hintergrund-Daemon holt die Daten asynchron ab und routet sie über Netzwerk (DLT over IP) oder UART, ohne den Aufrufer-Thread zu blockieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht-blockierendes Verhalten (Real-Time Safety):</strong> Da echtzeitkritische Cluster wie <code>Platform Health Management</code> und <code>Time Synchronization</code> denselben Logger nutzen, darf das Logging unter keinen Umständen blockieren (Zero-Allocation-Policy im Hot-Path, strikte Trennung von Erfassung und serialisiertem I/O-Transport).</li>\n<li><strong>Bootstrap-Dilemma & Early Logging:</strong></li>\n<li><code>Execution Management</code> startet als erster Plattform-Daemon und muss bereits loggen können, bevor der <code>Log and Trace</code>-Daemon betriebsbereit ist.</li>\n<li>Treiber- und Stack-Entwickler müssen einen Ringpuffer-Fallback (Local Buffer) für Plattform-Starts vorsehen, der nach Initialisierung von <code>Log and Trace</code> geleert wird.</li>\n<li><strong>Reentrancy & Thread-Safety:</strong> Alle Methoden der <code>Logger</code>-Schnittstelle müssen reentrant und threadsicher implementiert sein, da Cluster wie <code>Communication Management</code> massiv nebenläufig agieren.</li>\n<li><strong>Traceability & ASIL-Einstufung:</strong> Wenn Security- (IDSM) oder Safety-relevante (PHM) Cluster über <code>Logger</code> auditieren, müssen Datenverluste bei Pufferüberläufen (Buffer Overflow / Message Drop Counters) normativ erfasst und meldbar sein.</li>\n</ul>"}, {"id": "FIG-6b8e0a14adb6d799", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Architektur-Abhängigkeitsdiagramm (Component & Interface Dependency Diagram) gemäß AUTOSAR-Metamodell für die Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der durch den Functional Cluster (FC) <code>Log and Trace</code> bereitgestellten nativen Programmierschnittstelle (<code>Logger</code>) und deren querschnittlicher Abhängigkeiten (<code>«use»</code>) zu allen übrigen Standard-Functional-Clustern der AUTOSAR Adaptive Platform (Release R23-11, Kapitel 5.1).</li>\n<li><strong>Systemeinordnung:</strong> <code>Log and Trace</code> stellt das fundamentale Diagnose-, Tracing- und Protokollierungs-Rückgrat (<code>ara::log</code>) für Plattform-Daemons und Bibliotheken bereit, typischerweise mit Anbindung an das DLT-Protokoll (Diagnostic Log and Trace).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Bereitgestellte Schnittstelle:</strong></li>\n<li><code>«aapAPI, aapNativeInterface» Logger</code>: Zentrale C++ Abstraktion (<code>ara::log::Logger</code>) zur strukturierten und unstrukturierten Protokollierung.</li>\n<li><code>+ IsEnabled(): bool</code>: Abfrage des aktiven Log-Zustands zur Vermeidung unnötiger Formatierungs-Overheads mit explizit spezifiziertem booleschen Rückgabetyp.</li>\n<li><code>+ Log(MsgId, Params)</code>: Direktes, ID-basiertes Logging für formatfreie oder vorkompilierte DLT-Nachrichten.</li>\n<li><code>+ LogDebug(): LogStream</code>, <code>+ LogError(): LogStream</code>, <code>+ LogFatal(): LogStream</code>, <code>+ LogInfo(): LogStream</code>, <code>+ LogVerbose(): LogStream</code>, <code>+ LogWarn(): LogStream</code>: Severity-spezifische Factory-Methoden zur Erzeugung typsicherer Streaming-Objekte (<code>ara::log::LogStream</code>).</li>\n<li><code>+ WithLevel(): LogStream</code>: Dynamische Festlegung des Log-Levels zur Laufzeit.</li>\n<li><strong>Realisierende Komponente:</strong></li>\n<li><code>«aapFunctionalCluster» Log and Trace</code>: Implementiert das <code>Logger</code>-Interface (Realization-Pfeil mit geschlossener, nicht ausgefüllter Spitze).</li>\n<li><strong>Konsumierende Functional Clusters (<code>«use»</code>-Beziehung):</strong></li>\n<li><strong>Daemon-basierte Cluster (<code>daemon-based</code>):</strong></li>\n<li><code>Execution Management</code> (Prozesslebenszyklus, POSIX-Initialisierung)</li>\n<li><code>State Management</code> (Systemzustandssteuerung)</li>\n<li><code>Diagnostic Management</code> (UDS/DoIP-Stack)</li>\n<li><code>Platform Health Management</code> (Watchdog, Alive-/Deadline-Supervision)</li>\n<li><code>Time Synchronization</code> (gPTP / IEEE 802.1AS)</li>\n<li><code>Intrusion Detection System Manager</code> (Security Event Logging)</li>\n<li><code>Communication Management</code> (Service-Oriented Communication via SOME/IP, IPC)</li>\n<li><code>Vehicle Update and Configuration Management</code> (Fahrzeugweite Update-Orchestrierung)</li>\n<li><code>Update and Configuration Management</code> (Lokales Software-Package-Handling)</li>\n<li><code>Network Management</code> (Partielle Netzwerke, State Handling; nun explizit als prozess-/daemon-basiert deklariert)</li>\n<li><strong>Bibliotheks-/Nicht-Daemon-basierte Cluster:</strong></li>\n<li><code>Persistency</code> (Flash/EEPROM File & Key-Value Storage)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchroner Aufrufkontext:</strong> Der aufrufende Functional Cluster instanziiert oder referenziert thread-lokal ein <code>Logger</code>-Objekt (gebunden an Application-ID/Context-ID).</li>\n<li><strong>Filterung & Stream-Generierung:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Interner oder expliziter Check via <code>IsEnabled()</code> gegen den aktuell konfigurierten Log-Level.</li>\n<li>Bei Freigabe Erzeugung des temporären <code>LogStream</code>-Objekts (Stack-basiert).</li>\n<li>Formatierung/Serialisierung der Parameter über den überladenen Shift-Operator <code>operator&lt;&lt;</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Asynchroner Flush & IPC:</strong></li>\n<li>Mit Zerstörung des temporären <code>LogStream</code>-Objekts am Ende des Full-Expressions (RAII) erfolgt die Commit-Operation.</li>\n<li>Übergabe der Nachricht an den lokalen Puffer bzw. Shared-Memory-Ringpuffer.</li>\n<li>Der <code>Log and Trace</code>-Hintergrund-Daemon holt die Daten asynchron ab und routet sie über Netzwerk (DLT over IP) oder UART, ohne den Aufrufer-Thread zu blockieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht-blockierendes Verhalten (Real-Time Safety):</strong> Da echtzeitkritische Cluster wie <code>Platform Health Management</code> und <code>Time Synchronization</code> denselben Logger nutzen, darf das Logging unter keinen Umständen blockieren (Zero-Allocation-Policy im Hot-Path, strikte Trennung von Erfassung und serialisiertem I/O-Transport).</li>\n<li><strong>Bootstrap-Dilemma & Early Logging:</strong></li>\n<li><code>Execution Management</code> startet als erster Plattform-Daemon und muss bereits loggen können, bevor der <code>Log and Trace</code>-Daemon betriebsbereit ist.</li>\n<li>Treiber- und Stack-Entwickler müssen einen Ringpuffer-Fallback (Local Buffer) für Plattform-Starts vorsehen, der nach Initialisierung von <code>Log and Trace</code> geleert wird.</li>\n<li><strong>Reentrancy & Thread-Safety:</strong> Alle Methoden der <code>Logger</code>-Schnittstelle müssen reentrant und threadsicher implementiert sein, da Cluster wie <code>Communication Management</code> massiv nebenläufig agieren.</li>\n<li><strong>Traceability & ASIL-Einstufung:</strong> Wenn Security- (IDSM) oder Safety-relevante (PHM) Cluster über <code>Logger</code> auditieren, müssen Datenverluste bei Pufferüberläufen (Buffer Overflow / Message Drop Counters) normativ erfasst und meldbar sein.</li>\n</ul>"}], "trans": [{"from": "FIG-2ae999b1b55c74dc", "to": "FIG-d7bf0075ebd9cd51", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d7bf0075ebd9cd51", "to": "FIG-6b8e0a14adb6d799", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Logger</code>: Rückgabetyp bei Methode <code>+ IsEnabled(): bool</code> explizit ergänzt (zuvor <code>+ IsEnabled()</code>).</li>\n<li><code>Network Management</code>: Eigenschaftsauszeichnung <code>daemon-based</code> hinzugefügt (zuvor ohne Kennzeichnung als rein bibliotheksbasierter Cluster geführt).</li>\n<li><code>Vehicle Update and Configuration Management</code>: Redaktioneller Zeilenumbruch des Namens im Klassenrahmen geändert (<code>Vehicle Update and</code> / <code>Configuration Management</code> statt <code>Vehicle Update and Configuration</code> / <code>Management</code>).</li>\n</ul>"}]};
